        vm.assume(collectAmount <= putAmount + 1 ether); // bound collect
        vm.deal(caller, putAmount);
        vm.prank(caller);
        c.Put(block.timestamp + 1); // ensure unlockTime is in future

        uint256 balanceBefore = address(c).balance;
        uint256 accBalanceBefore = c.Acc(caller).balance;

        vm.warp(block.timestamp + 2); // past unlockTime
        vm.prank(caller);
        bool reverted = false;
        try c.Collect(collectAmount) {
            // success
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = address(c).balance;
        uint256 accBalanceAfter = c.Acc(caller).balance;

        // Rule: the sum of all balances in the contract cannot exceed the sum of ether in contract plus initial user balances
