pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 unlockTime, uint256 putAmount, uint256 collectAmount) public {
        vm.assume(caller != address(this));
        vm.assume(caller != address(0));
        vm.assume(putAmount > 0 && putAmount <= 100 ether);
        vm.assume(collectAmount > 0 && collectAmount <= 100 ether);
        vm.assume(unlockTime <= block.timestamp + 1000000);

        // Initial state: get sum of all balances (only caller's balance matters since others not involved)
        uint256 initialCallerBalance = c.Acc(caller).balance;
        uint256 initialContractBalance = address(c).balance;

        // Fund caller and call Put
        vm.deal(caller, putAmount);
        vm.prank(caller);
        c.Put{value: putAmount}(unlockTime);

        // Try to collect
        bool reverted;
        vm.prank(caller);
        (bool success, ) = address(c).call{gas: 100000}(abi.encodeWithSignature("Collect(uint256)", collectAmount));
        reverted = !success;

        // After: compute new sum of all balances (only caller's balance changed)
        uint256 finalCallerBalance = c.Acc(caller).balance;
        uint256 finalContractBalance = address(c).balance;

        // Rule: final total of all user balances must not exceed initial total + contract ether increase minus amounts collected (no overflow inflation)
        // More concretely: finalCallerBalance <= initialCallerBalance + (finalContractBalance - initialContractBalance) + (collectAmount if !reverted else 0)
        uint256 contractChange = finalContractBalance - initialContractBalance; // may be negative but safe due to unchecked
        bool rule = reverted || (finalCallerBalance <= initialCallerBalance + contractChange + collectAmount);
        assertTrue(rule);
    }
}

