pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint256 depositAmount, uint256 withdrawAmount) public {
        // Bound inputs to reasonable ranges
        unlockTime = bound(unlockTime, block.timestamp, block.timestamp + 100);
        depositAmount = bound(depositAmount, 0, 10 ether);
        withdrawAmount = bound(withdrawAmount, 1 ether, 10 ether);

        // Ensure enough balance for withdrawal
        c.Put{value: depositAmount}(unlockTime);

        // Record caller's balance before Collect
        uint256 balanceBefore = c.Acc(address(this)).balance;

        // Try to collect
        (bool success, ) = address(c).call{gas: 100000}(abi.encodeWithSignature("Collect(uint256)", withdrawAmount));

        // Get caller's balance after Collect
        uint256 balanceAfter = c.Acc(address(this)).balance;

        // Rule: If Collect succeeded, the caller's balance decreased by exactly withdrawAmount (no underflow, no overflow)
        // If it reverted, balance stayed the same
        assertTrue(
            (success && balanceAfter == balanceBefore - withdrawAmount) ||
            (!success && balanceAfter == balanceBefore)
        );
    }
}

