import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint _unlockTime, uint _deposit, uint _collectAmt) public {
        vm.assume(_deposit > 0 && _deposit <= 100 ether);
        vm.assume(_collectAmt > 0 && _collectAmt <= _deposit);
        vm.deal(address(this), 100 ether);
        // Deposit
        c.Put{value: _deposit}(_unlockTime);
        // Warp to after unlock time to allow Collect
        vm.warp(block.timestamp + _unlockTime + 1);
        // Get the balance before Collect
        uint balanceBefore = address(this).balance;
        // Attempt Collect
        bool success;
        try c.Collect(_collectAmt) {
            success = true;
        } catch {
            success = false;
        }
        uint balanceAfter = address(this).balance;
        // The property: if Collect succeeds, the msg.sender's ether balance should decrease by exactly _collectAmt
        // and the contract's balance should also decrease by _collectAmt (since the contract paid out).
        uint contractBalanceAfter = address(c).balance;
        // We know the original contract only pays when block.timestamp > unlockTime and balance >= MinSum (1 ether) and balance >= _collectAmt.
        // _deposit >= MinSum ensures the condition is met.
        vm.assume(_deposit >= c.MinSum());
        // If Collect succeeded, we must have paid out exactly _collectAmt
        assertTrue(!success || (balanceAfter == balanceBefore - _collectAmt && contractBalanceAfter == 0));
    }
}

