pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmount, uint256 unlockTime, uint256 collectAmount) public {
        // Precondition: depositAmount bounded to reasonable value to avoid overflow
        vm.assume(depositAmount > 0 && depositAmount < 1e18);
        vm.assume(collectAmount > 0 && collectAmount <= depositAmount);
        unlockTime = bound(unlockTime, block.timestamp + 1, block.timestamp + 1000);

        // Caller deposits
        address caller = address(0x1234);
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Put{value: depositAmount}(unlockTime);

        // Fast forward time past unlockTime
        vm.warp(unlockTime + 1);

        // Caller tries to collect
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // After Collect, the caller's balance in contract must be >= 0 (i.e., non-negative)
        // Since balance is uint, it's always >= 0, but the assertion is about the invariant that
        // if Collect succeeded, the balance did not underflow.
        // For reference C: balance decreases by collectAmount only if conditions met, so balance >= 0 always.
        // For buggy M: unlockTime is ignored, so Collect may revert when it should succeed, but the invariant holds.
        // Actually, we need a rule that reference always satisfies and mutant breaks. 
        // The mutant may revert incorrectly, so the assertion should be: if Collect succeeded, then balance >= collectAmount before call.
        // Simpler: After the call, the balance in the contract for caller is non-negative (always true) but we need something that breaks.
        // Let's restate: The caller's balance in contract after Collect must be >= 0, but that's always true.
        // A better rule: If Collect succeeded, then (old balance - collectAmount) equals new balance.
        uint256 oldBalance = c.Acc(caller).balance;
        uint256 newBalance = c.Acc(caller).balance;
        if (success) {
            assertTrue(newBalance == oldBalance - collectAmount, "Balance subtraction correct");
        }
    }
}

