import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 amount, uint256 unlockTime) public {
        vm.assume(caller != address(0));
        vm.assume(unlockTime <= block.timestamp + 1000000);
        vm.assume(amount <= 1000000 ether);

        vm.deal(caller, amount);

        vm.prank(caller);
        c.Put(unlockTime);

        vm.prank(caller);
        (bool success,) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", amount));

