pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, uint unlockTime, uint putAmt, uint collectAmt) public {
        vm.assume(sender != address(0) && sender != address(c));
        vm.deal(sender, putAmt + 1 ether);

        // First, put some ether to satisfy MinSum and create a record
        vm.prank(sender);
        c.Put{value: putAmt}(unlockTime);

        // Ensure unlockTime is in the past so Collect can succeed
        vm.warp(block.timestamp + 1000);

        // Collect with the specified amount
        vm.prank(sender);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmt));

        // If Collect succeeded, check that the last Log event matches the actual balance change
        if (success) {
            // Read the last Log entry
            (address logSender, string memory data, uint val, uint time) = c.LogFile().History(c.LogFile().History.length() - 1);
            // The actual balance subtracted is min(collectAmt, balance after Put) but the bug subtracts 1
            // So rule: the logged val should equal the actual amount subtracted (which is collectAmt if collectAmt <= balance, else 0 due to revert)
            // Since we know success implies collectAmt <= balance (due to checks), the logged val should be collectAmt
            assertTrue(val == collectAmt, "Logged value should equal collect amount");
        }
    }
}

