pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, uint256 unlockDelay, uint256 depositAmount, uint256 collectAmount) public {
        // Bound inputs to realistic ranges
        unlockDelay = bound(unlockDelay, 1, 1000000);
        depositAmount = bound(depositAmount, 1 ether, 100 ether);
        collectAmount = bound(collectAmount, 1, depositAmount); // collect up to deposit

        // Setup: fund the contract and deposit from caller
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Put{value: depositAmount}(block.timestamp + unlockDelay);

        // Record balances before Collect
        uint256 callerBalanceBefore = caller.balance;

        // Warp to after unlock time
        vm.warp(block.timestamp + unlockDelay + 1);

        // Attempt Collect
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // If call succeeded, caller should have gained exactly collectAmount
        if (success) {
            uint256 callerBalanceAfter = caller.balance;
            assertTrue(callerBalanceAfter == callerBalanceBefore + collectAmount, "Caller must gain exactly collectAmount");
        } else {
            // If reverted, caller's balance unchanged
            assertTrue(caller.balance == callerBalanceBefore, "Caller balance unchanged on revert");
        }
    }
}

